package cosic.script.next.catalogue

/*
 * The documentation of the functions the language had before it ran Strudel's, as the reference of the app listed it: one entry per
 * function, with its aliases. Until the functions of the parity plan are documented from Strudel's own text (task 2.12) this is what
 * `reference()` shows; the functions themselves are registered in `Legacy.kt`.
 */

private fun legacy(category: String, names: String, signature: String, text: String, example: String, snippet: String = "\$: $example") =
    Catalogue.document(names.split(' '), Doc(signature, text, example, true, category, snippet))

internal fun registerLegacyDocs() {
    legacy("Constructors", "silence", "silence", "A pattern with no events, handy as a placeholder or an empty section.", "\$: silence", "\$: silence")
